 if($('#feed-form')){installRecovery($('#feed-form'),()=>JSON.stringify({schedule:state.scheduleVersion,participants:active().map(a=>[a.id,a.phase])}));feedSummary();$('#feed-form').oninput=feedSummary;$('#feed-offer').onchange=e=>{state.phase.forEach(p=>{const v=groupExpected(p.id,e.target.value);$(`[name="liters-${p.id}"]`).value=v;$(`[data-expected="${p.id}"]`).textContent=num(v)});feedSummary()};$('#feed-form').onsubmit=e=>{e.preventDefault();const p=feedSummary(),fd=new FormData(e.target),time=fd.get('time')||null,offerId=fd.get('offerId')||null,note=String(fd.get('note')).trim(),diff=p.inputs.some(x=>Number(x.value)!==groupExpected(x.name.split('-')[1],offerId));const error=p.total<=0?'Informe um volume positivo.':p.missing?'Estoque insuficiente para este fornecimento.':diff&&!note?'Informe o motivo das diferenças.':null;if(error){$('#feed-error').hidden=false;$('#feed-error').textContent=error;return}const groups=p.inputs.map(x=>({phase:x.name.split('-')[1],liters:Number(x.value),participants:active().filter(a=>a.phase===x.name.split('-')[1]).map(a=>a.id)}));if(groups.some(g=>g.liters>0&&!g.participants.length)){toast('Há volume sem participantes. Confira as coleiras.');return}const items=groups.flatMap(g=>allocateLiters(g.liters,g.participants));state.stock.nc=round3(state.stock.nc-p.nc);state.stock.com=round3(state.stock.com-p.com);state.feeds.push({id:'F'+String(state.feeds.length+1).padStart(3,'0'),offerId,offerLabel:offerLabel(offerId),scheduleVersion:state.scheduleVersion,date:'2026-10-28',time,nc:p.nc,com:p.com,total:p.total,ncCost:Math.round(p.nc*1.4*100)/100,comCost:Math.round(p.com*1.6*100)/100,cost:(Math.round(p.nc*1.4*100)+Math.round(p.com*1.6*100))/100,note,groups,items});persist();location.hash='alimentacao';toast('Fornecimento registrado na prévia.')}}
 if($('#config-form')){let draft=(state.scheduleDraft||state.schedule).map(x=>({...x}));const read=()=>{draft=[...document.querySelectorAll('[data-schedule-id]')].map(row=>({id:row.dataset.scheduleId,time:row.querySelector('[data-time]').value,share:row.querySelector('[data-share]').value}));};const redraw=()=>{$('#schedule-fields').innerHTML=scheduleFields(draft);document.querySelectorAll('[data-delete-offer]').forEach(b=>b.onclick=()=>{read();draft=draft.filter(x=>x.id!==b.dataset.deleteOffer);redraw()})};$('#add-offer').onclick=()=>{read();draft.push({id:'OP'+String(state.nextOffer++).padStart(3,'0'),time:'',share:''});persist();redraw()};$('#save-schedule-draft').onclick=()=>{read();state.scheduleDraft=draft.map(x=>({...x}));persist();toast('Rascunho salvo; a previsão continua usando a programação ativa.')};redraw();$('#config-form').onsubmit=e=>{e.preventDefault();read();const fd=new FormData(e.target),phases=state.phase.map(p=>({...p,name:String(fd.get('name-'+p.id)),collar:String(fd.get('collar-'+p.id)),color:String(fd.get('color-'+p.id)),liters:Number(fd.get('dose-'+p.id))})),positive=phases.some(p=>p.liters>0),error=!draft.length&&positive?'Adicione pelo menos uma oferta para doses positivas.':draft.length&&Math.abs(draft.reduce((n,x)=>n+Number(x.share),0)-100)>.001?'Distribua 100% do volume diário entre as ofertas.':null;if(error){$('#config-error').textContent=error;$('#config-error').hidden=false;return}const schedule=draft.map(x=>({...x,share:Number(x.share)}));if(state.feeds.length){state.pendingConfig={phase:phases,schedule,version:state.scheduleVersion+1};delete state.scheduleDraft;persist();toast('Rotina salva para 29/10; ofertas de hoje preservadas.');return}state.phase=phases;state.schedule=schedule;state.scheduleVersion++;delete state.scheduleDraft;persist();render();toast('Rotina atualizada na prévia.')};}
 for(const [id,key] of [['brix-form','brix'],['colostro-config','weight']])if($('#'+id))$('#'+id).onsubmit=e=>{e.preventDefault();state.refs[key]=Number(new FormData(e.target).get(key));persist();toast('Referência salva na prévia.')};
